#include <iostream>

class Contatore {
public:
    explicit Contatore(int valore) : valore_(valore) {}
    void incrementa() { ++valore_; }
    int valore() const { return valore_; }
private:
    int valore_;
};

int main() {
    Contatore c(4);
    c.incrementa();
    std::cout << c.valore() << std::endl;
}
